const payload = $input.first().json;
const rawText = payload.text || payload.body?.content || payload.message || '';

const extract = (label) => {
  const regex = new RegExp(`${label}[:\\s]+([^|\\n]+)`, 'i');
  const match = rawText.match(regex);
  return match ? match[1].trim() : '';
};

const newHire = {
  fullName:    extract('Name') || extract('Employee') || 'New Employee',
  role:        extract('Role') || extract('Title') || extract('Position') || 'Team Member',
  department:  extract('Department') || extract('Team') || 'General',
  startDate:   extract('StartDate') || extract('Start Date') || extract('Start') ||
               new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
  managerEmail: extract('Manager') || extract('ReportsTo') || '',
  location:    extract('Location') || extract('Office') || 'Remote',
  email:       extract('Email') || extract('WorkEmail') || ''
};

const folderName = `${newHire.fullName} - ${newHire.role} - ${newHire.startDate}`
  .replace(/[<>:"/\\|?*]/g, '-').trim();

const SHAREPOINT_SITE_ID           = 'REPLACE_WITH_YOUR_SHAREPOINT_SITE_ID';
const SHAREPOINT_LIST_ID           = 'REPLACE_WITH_YOUR_ONBOARDING_LIST_ID';
const ONEDRIVE_PARENT_FOLDER_PATH  = '/HR/NewHires'; 
const TEAMS_HR_TEAM_ID             = 'REPLACE_WITH_YOUR_HR_TEAM_ID';
const TEAMS_ONBOARDING_CHANNEL_ID  = 'REPLACE_WITH_YOUR_ONBOARDING_CHANNEL_ID';
const OUTLOOK_HR_MAILBOX           = 'user@example.com';

return [{
  json: {
    ...newHire,
    folderName,
    SHAREPOINT_SITE_ID,
    SHAREPOINT_LIST_ID,
    ONEDRIVE_PARENT_FOLDER_PATH,
    TEAMS_HR_TEAM_ID,
    TEAMS_ONBOARDING_CHANNEL_ID,
    OUTLOOK_HR_MAILBOX,
    rawText,
    triggeredAt: new Date().toISOString()
  }
}];

const basePath = $('Parse New Hire + Config').first().json.ONEDRIVE_PARENT_FOLDER_PATH
  + '/' + $('Parse New Hire + Config').first().json.folderName;

const subFolders = ['01 - Contracts', '02 - Equipment', '03 - Training', '04 - Benefits', '05 - Personal Documents'];

return subFolders.map(folder => ({
  json: { folderPath: `${basePath}/${folder}`, newHireData: $('Parse New Hire + Config').first().json }
}));

const hire = $('Parse New Hire + Config').first().json;

// Dynamically pull execution results from the true parallel branches
const spItem = $('SharePoint: Create Onboarding Entry').first().json || {};
const odFolder = $('OneDrive: Create Employee Folder').first().json || {};
const teamsChannel = $('Teams: Create Onboarding Channel').first().json || {};
const emailRes = $('Outlook: Send Welcome Email').first().json || {};

const spSuccess = spItem.id ? `✅ SharePoint List Item ID: ${spItem.id}` : '❌ SharePoint List Update Failed';
const odSuccess = odFolder.webUrl ? `✅ [OneDrive Folder Provisioned](${odFolder.webUrl})` : '❌ OneDrive Provisioning Failed';
const teamsSuccess = teamsChannel.webUrl ? `✅ [Teams Channel Created](${teamsChannel.webUrl})` : '❌ Teams Channel Creation Failed';
const emailSuccess = emailRes.id ? `✅ Welcome email sent to ${hire.email}` : '❌ AI Generation or Email Failed';

const adaptiveCard = {
  type: 'AdaptiveCard',
  '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json',
  version: '1.5',
  body: [
    {
      type: 'TextBlock',
      text: `🎉 New Team Member Onboarded: ${hire.fullName}`,
      weight: 'Bolder',
      size: 'Medium',
      color: 'Good',
      wrap: true
    },
    {
      type: 'FactSet',
      facts: [
        { title: 'Role',        value: hire.role },
        { title: 'Department',  value: hire.department },
        { title: 'Start Date',  value: hire.startDate },
        { title: 'Location',    value: hire.location },
        { title: 'Manager',     value: hire.managerEmail || 'TBD' }
      ]
    },
    {
      type: 'TextBlock',
      text: '**Onboarding Task Status:**',
      weight: 'Bolder',
      spacing: 'Medium'
    },
    {
      type: 'TextBlock',
      text: `${spSuccess}\n${odSuccess}\n${teamsSuccess}\n${emailSuccess}`,
      wrap: true,
      spacing: 'None'
    }
  ]
};

return [{
  json: {
    adaptiveCard: JSON.stringify(adaptiveCard),
    teamId:     hire.TEAMS_HR_TEAM_ID,
    channelId:  hire.TEAMS_ONBOARDING_CHANNEL_ID
  }
}];

const errorData = $input.first().json;

const adaptiveCard = {
  type: 'AdaptiveCard',
  '$schema': 'http://adaptivecards.io/schemas/adaptive-card.json',
  version: '1.5',
  body: [
    {
      type: 'TextBlock',
      text: `🚨 Onboarding Workflow Critical Failure`,
      weight: 'Bolder',
      size: 'Medium',
      color: 'Attention',
      wrap: true
    },
    {
      type: 'FactSet',
      facts: [
        { title: 'Failed Node',  value: errorData.execution.lastNodeExecuted },
        { title: 'Error Message', value: errorData.execution.error.message },
        { title: 'Workflow ID',  value: errorData.workflow.id }
      ]
    }
  ]
};

return [{
  json: {
    adaptiveCard: JSON.stringify(adaptiveCard),
    teamId: 'REPLACE_WITH_YOUR_HR_TEAM_ID',
    channelId: 'REPLACE_WITH_YOUR_ONBOARDING_CHANNEL_ID'
  }
}];
